entries[63477] = { ["name"] = "Schlackentopf", ["text"] = "Unbegrenzte Reichweite\nSofort\nStürmt ein zufälliges feindliches Ziel an, ergreift es und wirft es in den Schlackentopf. Das Ziel kann den Zaubernden nicht angreifen und erleidet 10 Sek. lang pro Sekunde 6000 Feuerschaden. Wenn das Ziel überlebt, wird es von der magischen Schlacke gestärkt, die 10 Sek. lang das Tempo um 100% erhöht." }
