entries[63765] = { ["name"] = "Elastisches Arachnogewebe", ["text"] = "Wirken in 5 sek.\nBenötigt Umhang\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nFroststoff (12), Überladener Kondensator\nBringt an einem Umhang dauerhaft ein elastisches Arachnogewebe an, das es Euch gestattet, Euren Umhang 30 Sek. lang als Fallschirm zu nutzen.\n\nDer Umhang kann nur einmal pro Minute genutzt werden und benötigt eine Ingenieursfertigkeit von mindestens 350." }
